 if($action==='room_map_save'){$connection=(int)$_POST['connection_id'];$property=(int)$_POST['property_id'];$check=$pdo->prepare('SELECT id FROM channel_connections WHERE id=? AND supplier_id=?');$check->execute([$connection,$u['supplier_id']]);if(!$check->fetch())throw new RuntimeException('Bağlantı yetkisi bulunamadı.');$check=$pdo->prepare('SELECT id FROM properties WHERE id=? AND supplier_id=?');$check->execute([$property,$u['supplier_id']]);if(!$check->fetch())throw new RuntimeException('Ürün bulunamadı.');$roomInputs=$_POST['rooms']??[];if(!is_array($roomInputs))$roomInputs=[];$valid=$pdo->prepare('SELECT id FROM room_types WHERE id=? AND property_id=?');$up=$pdo->prepare("INSERT INTO channel_room_mappings(channel_connection_id,property_id,room_type_id,external_room_id,status) VALUES(?,?,?,?,'confirmed') ON CONFLICT(channel_connection_id,room_type_id) DO UPDATE SET external_room_id=EXCLUDED.external_room_id,property_id=EXCLUDED.property_id,status='confirmed',suggested_at=NULL");$del=$pdo->prepare('DELETE FROM channel_room_mappings WHERE channel_connection_id=? AND property_id=? AND room_type_id=?');$delSug=$pdo->prepare("DELETE FROM channel_room_mappings WHERE channel_connection_id=? AND external_room_id=? AND room_type_id<>? AND status='suggested'");$saved=0;$mapErrors=[];foreach($roomInputs as $rid=>$external){$rid=(int)$rid;$external=trim((string)$external);if(!$rid)continue;$valid->execute([$rid,$property]);if(!$valid->fetch())continue;try{if($external===''){$del->execute([$connection,$property,$rid]);}else{$delSug->execute([$connection,$external,$rid]);$up->execute([$connection,$property,$rid,$external]);}$saved++;}catch(Throwable $e){$mapErrors[]='Oda #'.$rid.' kaydedilemedi: '.$e->getMessage();}}$message=$saved.' oda eşleştirmesi kaydedildi.'.($mapErrors?' Uyarılar: '.implode('; ',$mapErrors):'');$roomEdit=['connection_id'=>$connection,'property_id'=>$property];}
