 if($action==='room_map_reject'){$mapId=(int)$_POST['mapping_id'];$stmt=$pdo->prepare("DELETE FROM channel_room_mappings WHERE id=? AND status='suggested' AND channel_connection_id IN (SELECT id FROM channel_connections WHERE supplier_id=?)");$stmt->execute([$mapId,$u['supplier_id']]);$message=$stmt->rowCount()>0?'Öneri reddedildi ve kaldırıldı.':'Öneri bulunamadı.';$roomEdit=['connection_id'=>(int)$_POST['connection_id'],'property_id'=>(int)$_POST['property_id']];}
}}
catch(Throwable $e){$error=$e->getMessage();}
// Migration 044 öncesi kayıtlar için token'ları uçur (UNIQUE index token üretirken takılmasın).
